package pattern_matching;

import java.util.Scanner;
public class PatternMatching {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		        int rows = 5;

		        for (int i = 1; i <= rows; i++) {
		            
		            for (int j = i; j < rows; j++) {
		                System.out.print(" ");
		            }
		          
		          
		                System.out.print("*");
		            }
		            System.out.println(); 
		        }
		    }
		

	
	


